def fit(cols,names,show=True):
    X=np.array(cols).T
    c,_,_,_=np.linalg.lstsq(X,dA_dt,rcond=None)
    r=np.mean((X@c-dA_dt)**2)/np.var(dA_dt)
    if show:
        print('NMSE',r)
        for n,v in zip(names,c):
            if abs(v)>1e-3: print(n,round(v,4))
    return r
